INSERT INTO `points_products` VALUES (17, '加浓缩券', '下单时可额外添加1份浓缩，可与主券叠加使用', '/uploads/images/2026/01/abe8facbc6fc4d61805dce1f65e6ca17.png', 80, NULL, 91, 'active', 'coupon', '2026-01-04 11:54:32', '2026-01-15 17:52:22', 'PHYSICAL', 'SHOT', 1, NULL, NULL, NULL, NULL, 30);
INSERT INTO `points_products` VALUES (18, '配送费抵扣券', '仅抵扣外卖订单配送费，可与主券叠加使用,最高可抵扣配送费3元', '/uploads/images/2026/01/de8872b5331e41beacd46a5a33deb2fd.png', 120, NULL, 92, 'active', 'coupon', '2026-01-04 12:03:48', '2026-01-15 17:52:22', 'PHYSICAL', 'DELIVERY_FEE', 3, NULL, NULL, NULL, 10, 30);
INSERT INTO `points_products` VALUES (19, '5元代金券', '', '/uploads/images/2026/01/85ea8153ff034de5ab6deb193401f940.png', 150, NULL, 97, 'active', 'coupon', '2026-01-04 12:06:36', '2026-01-15 17:52:22', 'PHYSICAL', 'FULL_REDUCE', 5, NULL, 0, NULL, 2, 30);
INSERT INTO `points_products` VALUES (20, '全场饮品通兑券', '通兑券将自动抵扣订单中价格最高的饮品(最高40元)', '/uploads/images/2026/01/59eaa7acf66f489a8a07227362622e94.png', 800, NULL, 95, 'active', 'coupon', '2026-01-04 12:30:24', '2026-01-15 17:52:22', 'PHYSICAL', 'EXCHANGE', NULL, NULL, NULL, NULL, 10, 14);
INSERT INTO `points_products` VALUES (21, 'Cozy 品牌贴纸包', '精选多款 Cozy 主题原创插画贴纸。采用防水材质，无论是贴在笔记本电脑、手机壳还是手账本上，都能随时随地随身携带一份“惬意”，让你的私人物品瞬间变身。', '/uploads/images/2026/01/379674aff01448e5915519dda3b9e7b0.png', 100, NULL, 100, 'active', 'gift', '2026-01-04 16:46:30', '2026-01-04 16:48:39', 'PHYSICAL', NULL, NULL, NULL, NULL, NULL, NULL, 7);
INSERT INTO `points_products` VALUES (22, '定制拿铁金搅拌勺', '专为 CozyCoffee 定制的优雅“拿铁金”色泽不锈钢搅拌勺。勺柄末端精细刻印品牌 Logo，手感沉稳。每一次搅动杯中咖啡，不仅是融合风味，更充满了生活的仪式感。', '/uploads/images/2026/01/e8aee7f322c94e9fa1df2f3e293c5bdc.png', 600, NULL, 98, 'active', 'gift', '2026-01-04 16:48:32', '2026-01-04 16:50:37', 'PHYSICAL', NULL, NULL, NULL, NULL, NULL, 1, 7);
INSERT INTO `points_products` VALUES (23, '拿铁金定制马克杯', '积分商城人气 No.1 单品。采用独特的哑光拿铁金釉面工艺，触感温润。人体工学手柄设计，握感舒适。它不仅是一个咖啡杯，更是你办公桌上最吸睛的“Cozy 陪伴”。', '/uploads/images/2026/01/acaa962a0755470b89476a2dbd88e307.png', 1200, NULL, 100, 'active', 'gift', '2026-01-04 16:49:07', '2026-01-04 16:50:33', 'PHYSICAL', NULL, NULL, NULL, NULL, NULL, 1, 7);
INSERT INTO `points_products` VALUES (24, 'Cozy 经典帆布包', '选用高磅数加厚原生帆布制作，结实耐用。极简的米色基底搭配经典的 CozyCoffee Logo 印花，内设实用收纳暗袋。无论是通勤、上课还是周末采购，它都是你最实用且时髦的日常单品。', '/uploads/images/2026/01/cac39e54b3934c208c3abafbd302e5d1.png', 1600, NULL, 99, 'active', 'gift', '2026-01-04 16:49:45', '2026-01-04 16:50:30', 'PHYSICAL', NULL, NULL, NULL, NULL, NULL, 1, 7);
INSERT INTO `points_products` VALUES (25, '“COZY”主题 T 恤', '【黄金及以上会员专享】 核心粉丝的身份认证。采用优质精梳棉面料，亲肤透气。复古风格的“COZY”主题印花设计，不仅舒适好穿，更是一种生活态度的低调表达，做 Cozy 社区的最佳代言人。', '/uploads/images/2026/01/8ede7558dc8a4ab9859223356f950ac5.png', 2200, NULL, 100, 'active', 'gift', '2026-01-04 16:50:17', '2026-01-04 16:50:25', 'PHYSICAL', NULL, NULL, NULL, NULL, NULL, 1, 7);
INSERT INTO `points_products` VALUES (26, '挂耳咖啡精选礼盒', '汇集全球优质产区的精选咖啡豆（如埃塞俄比亚、哥伦比亚等），制成便携挂耳包，随时随地享受精品风味。精美的定制礼盒包装，无论是自用“囤货”，还是作为礼物馈赠亲友，都诚意十足。', '/uploads/images/2026/01/a5cffdbfd6f94612a4f24222f462d4d3.png', 3500, NULL, 19, 'active', 'gift', '2026-01-04 16:51:22', '2026-01-04 16:51:22', 'PHYSICAL', NULL, NULL, NULL, NULL, NULL, 1, 7);
INSERT INTO `points_products` VALUES (27, '买一赠一券', '仅限饮品类:不适用于瓶装饮料、手冲咖啡、烘焙甜品及周边商品。\n不可分次核销：必须在单笔订单中包含至少两杯饮品方可触发，不支持\"存一杯\"操作。\n不与其他主券叠加：买一送一券属于主券类型，不可与折扣券、满减券同时使用。', '/uploads/images/2026/01/9e7177934eea4883b9e30e05f2442fec.png', 350, NULL, 95, 'active', 'coupon', '2026-01-10 17:05:00', '2026-01-15 17:18:56', 'PHYSICAL', 'BOGO', 40, NULL, NULL, NULL, 10, 7);
